CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key AUTO_INCREMENT not null, "name" varchar not null, "email" varchar not null, "password" varchar not null, "created_at" datetime, "updated_at" datetime, "role" varchar not null default 'gestionnaire');
INSERT INTO users VALUES(1,'dimossi sara janet','dimossisara@gmail.com','$2y$12$KJybwQnOC7NpYOgL.jb74uO6xRxpTuxS.SMARhEjIgf6TDbzWRsci','2026-02-07 16:40:11','2026-02-07 16:40:11','admin');
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key AUTO_INCREMENT not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key AUTO_INCREMENT not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "products" ("id" integer primary key AUTO_INCREMENT not null, "name" varchar not null, "code" varchar not null, "supplier" varchar, "price" numeric not null default '0', "stock" integer not null default '0', "min_stock" integer not null default '0', "optimal_stock" integer not null default '0', "category_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("category_id") references "categories"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "categories" ("id" integer primary key AUTO_INCREMENT not null, "code" varchar not null, "name" varchar not null, "parent_id" integer, "description" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "movements" ("id" integer primary key AUTO_INCREMENT not null, "product_id" integer not null, "type" varchar not null, "movement_type" varchar not null, "quantity" integer not null, "reason" text, "user_id" integer not null, "date" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "inventories" ("id" integer primary key AUTO_INCREMENT not null, "date" datetime not null, "user_id" integer not null, "status" varchar not null default 'draft', "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "inventory_items" ("id" integer primary key AUTO_INCREMENT not null, "inventory_id" integer not null, "product_id" integer not null, "expected_quantity" integer not null, "actual_quantity" integer not null, "difference" integer not null, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("inventory_id") references "inventories"("id") on delete cascade, foreign key("product_id") references "products"("id") on delete cascade);
PRAGMA writable_schema=ON;
